import'dart:math'as math;import'package:flutter/material.dart';
class DomainLabPainter extends CustomPainter{final String type;final double phase;DomainLabPainter(this.type,[this.phase=0]);@override void paint(Canvas c,Size s){c.drawRect(Offset.zero&s,Paint()..color=const Color(0xff081725));switch(type){case'Circuit':circuit(c,s);break;case'Free-body':fbd(c,s);break;case'Pedigree':pedigree(c,s);break;case'Food web':food(c,s);break;default:strata(c,s);}}void text(Canvas c,String t,Offset p,[double size=12]){final tp=TextPainter(text:TextSpan(text:t,style:TextStyle(color:Colors.white,fontSize:size)),textDirection:TextDirection.ltr)..layout();tp.paint(c,p);}void arrow(Canvas c,Offset a,Offset b,Paint p){c.drawLine(a,b,p);final q=math.atan2(b.dy-a.dy,b.dx-a.dx);for(final d in[-.5,.5])c.drawLine(b,b-Offset(math.cos(q+d),math.sin(q+d))*12,p);}
void circuit(Canvas c,Size s){final p=Paint()..color=Colors.white..strokeWidth=2..style=PaintingStyle.stroke;final y=s.height/2;c.drawLine(Offset(40,y),Offset(95,y),p);c.drawLine(Offset(95,y-28),Offset(95,y+28),p);c.drawLine(Offset(108,y-16),Offset(108,y+16),p);text(c,'Battery',const Offset(72,20));var x=130.0;c.drawLine(Offset(108,y),Offset(x,y),p);final path=Path()..moveTo(x,y);for(int i=0;i<8;i++){x+=18;path.lineTo(x,y+(i.isEven?-14:14));}path.lineTo(x+18,y);c.drawPath(path,p);text(c,'R = 10 Ω',Offset(160,y+28));c.drawLine(Offset(x+18,y),Offset(s.width-50,y),p);c.drawLine(Offset(s.width-50,y),Offset(s.width-50,y+90),p);c.drawLine(Offset(s.width-50,y+90),Offset(40,y+90),p);c.drawLine(Offset(40,y+90),Offset(40,y),p);arrow(c,Offset(130,y-35),Offset(230,y-35),Paint()..color=Colors.amber..strokeWidth=3);text(c,'I',const Offset(175,80));}
void fbd(Canvas c,Size s){final center=Offset(s.width/2,s.height/2),p=Paint()..strokeWidth=3; c.drawRect(Rect.fromCenter(center:center,width:80,height:60),Paint()..color=Colors.blueGrey);p.color=Colors.amber;arrow(c,center,center+const Offset(120,0),p);text(c,'Applied force',center+const Offset(45,-28));p.color=Colors.redAccent;arrow(c,center,center+const Offset(0,120),p);text(c,'mg',center+const Offset(8,80));p.color=Colors.greenAccent;arrow(c,center,center-const Offset(0,120),p);text(c,'Normal',center-const Offset(-8,105));final dash=Paint()..color=Colors.white38..strokeWidth=1;c.drawLine(Offset(20,center.dy),Offset(s.width-20,center.dy),dash);c.drawLine(Offset(center.dx,20),Offset(center.dx,s.height-20),dash);}
void pedigree(Canvas c,Size s){final p=Paint()..color=Colors.white..strokeWidth=2..style=PaintingStyle.stroke,a=Offset(s.width*.35,80),b=Offset(s.width*.65,80);c.drawRect(Rect.fromCenter(center:a,width:42,height:42),p);c.drawCircle(b,21,p);c.drawCircle(a,5,Paint()..color=Colors.amber);c.drawCircle(b,5,Paint()..color=Colors.amber);c.drawLine(a+const Offset(21,0),b-const Offset(21,0),p);final m=Offset(s.width/2,80);c.drawLine(m,m+const Offset(0,65),p);c.drawLine(Offset(s.width*.32,145),Offset(s.width*.68,145),p);for(final x in[s.width*.32,s.width*.44,s.width*.56,s.width*.68]){c.drawLine(Offset(x,145),Offset(x,185),p);c.drawCircle(Offset(x,205),20,p);}text(c,'□ male   ○ female   • carrier',Offset(20,s.height-35));}
void food(Canvas c,Size s){final p=Paint()..strokeWidth=3;final grass=Offset(s.width*.2,s.height*.75),herb=Offset(s.width*.5,s.height*.5),pred=Offset(s.width*.8,s.height*.22);for(final e in[[grass,herb],[herb,pred]]){p.color=Colors.greenAccent.withValues(alpha:.65+.25*math.sin(phase).abs());arrow(c,e[0],e[1],p);}for(final n in[[grass,'Grass'],[herb,'Herbivore'],[pred,'Predator']]){c.drawCircle(n[0]as Offset,30,Paint()..color=Colors.teal.shade700);text(c,n[1]as String,(n[0]as Offset)-const Offset(25,7));}text(c,'Animated arrows represent directional energy transfer',Offset(20,s.height-30));}
void strata(Canvas c,Size s){final colors=[Colors.brown.shade300,Colors.orange.shade200,Colors.blueGrey.shade300,Colors.amber.shade200];final h=(s.height-60)/4;for(int i=0;i<4;i++){final r=Rect.fromLTWH(s.width*.2,20+i*h,s.width*.6,h);c.drawRect(r,Paint()..color=colors[i]);text(c,'${300-i*80} Ma',Offset(s.width*.82,30+i*h));if(i==1){final path=Path()..moveTo(r.left,r.bottom);for(double x=r.left;x<r.right;x+=18)path.relativeLineTo(9,-6)..relativeLineTo(9,6);c.drawPath(path,Paint()..color=Colors.red.shade900..strokeWidth=2..style=PaintingStyle.stroke);text(c,'Unconformity',Offset(r.left+8,r.bottom-24));}if(i==2)text(c,'Fossil ◉',Offset(r.left+30,r.top+20));}text(c,'Stratigraphic column · oldest at bottom',Offset(20,s.height-28));}@override bool shouldRepaint(covariant DomainLabPainter o)=>o.type!=type||o.phase!=phase;}